// back for it.
//
// ROW_SPLIT (VIDEO.md M11c) is llm_attn_wmma.comp's P12-1 lane split for
// this kernel's plain bidirectional path. The row max above is KTIL passes a
// key block, each a tile store, two barriers and a scan in which BM lanes
// work (16 of 32 at QT=1) and each walks TILE cells serially. Here the whole
// block's scores are staged at once, RCL = WAVE/BM lanes share a row, each
// scans BN/RCL of its cells, and a clustered subgroup max folds them. A
// lane's row is the same in every block, so the running max lives in a
// register instead of LDS, and the corrections are built by all the lanes
// too. `stage` then holds QT*KTIL tiles, and bcorr moves into it, after the
// max is taken, since nothing else reads the scores out of LDS.
//
// It is bit-identical to the plain build: a max is exact under any
// reassociation, the cells each row maxes over are the same (the plain build
// masks none of them out of the max), and every other operation is the same
// one on the same operands.
#ifndef ROW_SPLIT
#define ROW_SPLIT 0
#endif
#if ROW_SPLIT
#if CAUSAL || WINDOW || REL_BIAS || TAIL_MAX || CROSS
#error "ROW_SPLIT covers the plain bidirectional build only"
#endif
#if BM > WAVE || (WAVE % BM) != 0 || KTIL < 2
#error "ROW_SPLIT needs BM to divide the wave and two score tiles a query tile"
#endif
#define RCL (WAVE / BM)     // lanes a row
#define RCPL (BN / RCL)     // cells a lane scans
shared float stage[QT * KTIL * TILE * TILE];
#define BCORR stage
#define BCORR_OFF (QT * TILE * TILE)
#else
shared float stage[QT * TILE * TILE];
#endif
// P, fp16, as the A operand of P.V -- row-major, leading dimension BN.
shared float16_t pbuf[BM * BN];
#if !ROW_SPLIT
// The row-constant correction matrix that rescales O and the row sums. Its
// counterpart, the row-constant running max, goes in `stage`.
shared float bcorr[QT * TILE * TILE];
#define BCORR bcorr
#define BCORR_OFF 0
shared float rowMax[BM];    // running max per query row, across key blocks
shared float blkMax[BM];    // this key block's max per query row
#endif
shared float rowSum[BM];    // softmax denominator, read out in the epilogue

