350	#endif
351	    uint qBase = pc.inOff + plane + (q0 / TILE) * (HDT * TILE * TILE);
352	    uint kBase = pc.kOff + kvPlane;
353	    uint vBase = pc.vOff + kvPlane;
354	
355	    // Q stays in registers for the whole sequence.
356	    FRAG_A fragQ[QT][HDT];
357	    [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
358	        [[unroll]] for (uint kt = 0u; kt < HDT; ++kt) {
359	            coopMatLoad(fragQ[qq][kt], hact, qBase + (qq * HDT + kt) * (TILE * TILE),
360	                TILE, gl_CooperativeMatrixLayoutRowMajor);
361	        }
362	    }
363	
364	    ACC o[QT][HDT];
365	    ACC lsum[QT];
366	    [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
367	        [[unroll]] for (uint j = 0u; j < HDT; ++j) {
368	            o[qq][j] = ACC(0.0);
369	        }
370	        lsum[qq] = ACC(0.0);
371	    }
372	    for (uint i = lane; i < BM; i += WAVE) {
373	        rowMax[i] = -1.0 / 0.0;
374	    }
375	    barrier();
376	
377	    const FRAG_B ones = FRAG_B(float16_t(1.0));
378	
379	#if CAUSAL
380	    // Nothing past this query block's last row can be attended to, so the
381	    // blocks beyond it are not read at all -- which at BM = BN is half the
382	    // key traffic of the bidirectional kernel, averaged over the grid.
383	    uint last = min(n, q0 + BM);
384	#elif WINDOW
385	    uint win = pc.span;
386	#if GROUP
387	    uint first = ((q0 / win) * win / BN) * BN;
388	    uint last = min(n, ((q0 + BM - 1u) / win + 1u) * win);
389	#else
390	    uint first = (q0 > win) ? ((q0 - win) / BN) * BN : 0u;
391	    uint last = min(n, q0 + BM + win);
392	#endif
393	#else
394	    uint last = n;
395	#endif
396	#if WINDOW
397	    for (uint base = first; base < last; base += BN) {
398	#else
399	    for (uint base = 0u; base < last; base += BN) {
400	#endif
401	        uint cnt = min(BN, n - base);
402	
403	        // ---- S = Q.K^T. K is the B operand and already K-contiguous, so it
404	        // is read straight out of the packed layout, no staging.
405	        ACC s[QT][KTIL];
406	        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
407	            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
408	                s[qq][kk] = ACC(0.0);
409	            }
410	        }
411	        [[unroll]] for (uint kt = 0u; kt < HDT; ++kt) {
412	            FRAG_B fragK[KTIL];
413	            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
414	                coopMatLoad(fragK[kk], hact, kBase + ((base / TILE + kk) * HDT + kt) * (TILE * TILE),
415	                    TILE, gl_CooperativeMatrixLayoutColumnMajor);
416	            }
417	            [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
418	                [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
419	                    s[qq][kk] = coopMatMulAdd(fragQ[qq][kt], fragK[kk], s[qq][kk]);
420	                }
421	            }
422	        }
423	
424	#if REL_BIAS
425	        // ---- The position term, straight out of memory onto the content
426	        // scores. Its plane is [aux1, aux1] per head, row-major, so a score
427	        // tile's bias is the tile at the same (query, key) corner.
428	        {
429	            uint bBase = pc.aux0 + head * pc.aux1 * pc.aux1;
430	            [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
431	                [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
432	                    ACC bias;
433	                    coopMatLoad(bias, act,
434	                        bBase + (q0 + qq * TILE) * pc.aux1 + base + kk * TILE,
435	                        pc.aux1, gl_CooperativeMatrixLayoutRowMajor);
436	                    s[qq][kk] += bias;
437	                }
438	            }
439	        }
440	#endif
441	
442	        // ---- Row max of this block. The scores are already scaled by
443	        // 1/sqrt(headDim)*log2(e) (folded into q by the pack), so everything
444	        // below is in log2 units and the exponential is exp2.
445	        for (uint i = lane; i < BM; i += WAVE) {
446	            blkMax[i] = -1.0 / 0.0;
447	        }
448	        barrier();
449	        [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
450	            [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
451	                coopMatStore(s[qq][kk], stage, qq * (TILE * TILE), TILE,
452	                    gl_CooperativeMatrixLayoutRowMajor);
453	            }
454	            barrier();
455	            for (uint i = lane; i < BM; i += WAVE) {
456	                uint qi = i / TILE, r = i % TILE;
457	                float mx = blkMax[i];
458	                for (uint c = 0u; c < TILE; ++c) {
459	#if CAUSAL
460	                    if (base + kk * TILE + c > q0 + i) {
461	                        break;      // and every c after it, the row is done
462	                    }
463	#endif
464	#if WINDOW
465	                    {
466	                        uint kj = base + kk * TILE + c;
467	                        if (kj >= n || OUT_OF_BAND(q0 + i, kj)) {
468	                            continue;
469	                        }
470	                    }
471	#endif
472	#if REL_BIAS || TAIL_MAX || CROSS
473	                    // The tail mask, applied to the *max* and not only to P.
474	                    //
475	                    // Every build masks the pad keys out of P, which is what
476	                    // removes them from the output and the row sum. Only this
477	                    // one has to keep them out of the max as well, and the
478	                    // reason is the position bias: a pad key scores exactly 0
479	                    // (zeroed k plane, zeroed bias) while a real key here
480	                    // scores tens of log2 units either side of it, because
481	                    // the bias is not small -- matrix_bd's rms is 13.7 where
482	                    // the content term's is 1. So on any row whose real
483	                    // scores are all negative, a key that does not exist
484	                    // would set the scale, and exp2(real - 0) would underflow
485	                    // fp16's smallest subnormal and take the whole row's
486	                    // softmax denominator to zero with it.
487	                    if (base + kk * TILE + c >= n) {
488	                        break;
489	                    }
490	#endif
491	                    mx = max(mx, stage[qi * (TILE * TILE) + r * TILE + c]);
492	                }
493	                blkMax[i] = mx;
494	            }
495	            barrier();
496	        }
497	
498	        // ---- Fold the block into the running max and build the two
499	        // row-constant matrices. exp2(-inf - m) is 0, which is exactly the
500	        // right correction for the first block, so there is no special case.
501	        for (uint i = lane; i < BM; i += WAVE) {
502	            uint qi = i / TILE, r = i % TILE;
503	            float mo = rowMax[i];
504	            float mn = max(mo, blkMax[i]);
505	            rowMax[i] = mn;
506	#if WINDOW
507	            // No key of this row's band seen yet: measure against 0, which
508	            // keeps corr at exp2(-inf) = 0 and the (masked) P finite-or-zero.
509	            if (mn == -1.0 / 0.0) {
510	                mn = 0.0;
511	            }
512	#endif
513	            float corr = exp2(mo - mn);
514	            for (uint c = 0u; c < TILE; ++c) {
515	                stage[qi * (TILE * TILE) + r * TILE + c] = mn;
516	                bcorr[qi * (TILE * TILE) + r * TILE + c] = corr;
517	            }
