package dit

import (
	"testing"

	"strix-halo-vulkan/safetensors"
	"strix-halo-vulkan/shaders"
	"strix-halo-vulkan/vk"
)

// coopMatLayout runs shaders/coopmat_layout_probe.comp and returns, per Use
// (A, B, fp32 accumulator, fp16 accumulator), per lane, the (row, column)
// each element index holds, as row*16 + column; -1 past the length.
func coopMatLayout(t *testing.T, dev *vk.Device) [4][32][]int {
	t.Helper()
	src32 := make([]float32, 256)
	src16 := make([]uint16, 256)
	for i := range src32 {
		src32[i] = float32(i)
		src16[i] = safetensors.F32ToF16(float32(i))
	}
	const slots = 32
	in32, err := dev.NewBuffer(256 * 4)
	if err != nil {
		t.Fatal(err)
	}
	defer in32.Destroy()
	in16, err := dev.NewBuffer(256 * 2)
	if err != nil {
		t.Fatal(err)
	}
	defer in16.Destroy()
	out, err := dev.NewBuffer(4 * 32 * slots * 4)
	if err != nil {
		t.Fatal(err)
	}
	defer out.Destroy()
	in32.WriteFloat32(src32)
	in16.WriteUint16At(0, src16)
	mod, err := dev.NewShaderModule(shaders.CoopMatLayoutProbe)
	if err != nil {
		t.Fatal(err)
	}
	defer mod.Destroy()
	pipe, err := dev.NewPipeline(mod, vk.PipelineSpec{Buffers: []*vk.Buffer{in32, in16, out}, RequiredSubgroupSize: 32})
	if err != nil {
		t.Fatal(err)
	}
	defer pipe.Destroy()
	if _, err := vk.DispatchMultiTimed([]vk.MultiDispatch{{Pipeline: pipe, GroupsX: 1, GroupsY: 1}}, 1, 1, true); err != nil {
		t.Fatal(err)
	}
	got := out.ReadFloat32(4 * 32 * slots)
	var lay [4][32][]int
	for u := range lay {
		for l := range lay[u] {
			for e := 0; e < slots; e++ {
				v := got[(u*32+l)*slots+e]
				if v < 0 {
					break
				}
				lay[u][l] = append(lay[u][l], int(v))
			}
		}
	}
	return lay
}

// TestCoopMatLayout pins the element order h3_attn_t.comp is written
// against (VIDEO.md M11c). On RADV/gfx1151 at wave32:
//
//   - A (fp16): lane l holds row l%16, element e its column e.
//   - B (fp16): lane l holds column l%16, element e its row e.
//   - accumulators (fp32 and fp16): lane l holds column l%16, element e
//     its row 2e + l/16.
//
// A driver that orders them otherwise fails here, and the transposed
// attention is then wrong, not slow.
func TestCoopMatLayout(t *testing.T) {
	dev, done := newTestDevice(t)
	defer done()
	lay := coopMatLayout(t, dev)
	names := []string{"A", "B", "acc32", "acc16"}
	for u := range lay {
		for l := range lay[u] {
			if l < 2 || l == 16 || l == 17 {
				t.Logf("%s lane %2d: %v", names[u], l, lay[u][l])
			}
		}
	}
	for l := 0; l < 32; l++ {
		for u, want := range []func(e int) int{
			func(e int) int { return (l%16)*16 + e },
			func(e int) int { return e*16 + l%16 },
			func(e int) int { return (2*e+l/16)*16 + l%16 },
			func(e int) int { return (2*e+l/16)*16 + l%16 },
		} {
			n := 16
			if u >= 2 {
				n = 8
			}
			if len(lay[u][l]) != n {
				t.Fatalf("%s lane %d: %d elements, want %d", names[u], l, len(lay[u][l]), n)
			}
			for e, v := range lay[u][l] {
				if v != want(e) {
					t.Fatalf("%s lane %d element %d: holds (%d, %d), want (%d, %d)", names[u], l, e,
						v/16, v%16, want(e)/16, want(e)%16)
				}
			}
		}
	}
}

