    [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
        [[unroll]] for (uint kt = 0u; kt < HDT; ++kt) {
            coopMatLoad(fragQ[qq][kt], hact, qBase + (qq * HDT + kt) * (TILE * TILE),
                TILE, gl_CooperativeMatrixLayoutColumnMajor);
        }
    }

    ACC o[QT][HDT];         // O^T: rows are head components, columns queries
    float runMax[QT];       // this lane's query's running max, a tile each
    float runSum[QT];       // and its share of the denominator (its half's keys)
    [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
        [[unroll]] for (uint j = 0u; j < HDT; ++j) {
            o[qq][j] = ACC(0.0);
        }
        runMax[qq] = -1.0 / 0.0;
        runSum[qq] = 0.0;
    }

    for (uint base = 0u; base < n; base += BN) {
        uint cnt = min(BN, n - base);

        // ---- S^T = K . Q^T.
        ACC s[QT][KTIL];
        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
                s[qq][kk] = ACC(0.0);
            }
        }
        [[unroll]] for (uint kt = 0u; kt < HDT; ++kt) {
            FRAG_A fragK[KTIL];
            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
                coopMatLoad(fragK[kk], hact, kBase + ((base / TILE + kk) * HDT + kt) * (TILE * TILE),
                    TILE, gl_CooperativeMatrixLayoutRowMajor);
            }
            [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
                [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
                    s[qq][kk] = coopMatMulAdd(fragK[kk], fragQ[qq][kt], s[qq][kk]);
                }
            }
        }

        // ---- The softmax, in registers: a lane's elements of s[qq][kk] are
        // its query's scores against keys kk*16 + 2e + half.
        FRAG_B fragP[QT][KTIL];
        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
            float mx = -1.0 / 0.0;
            if (cnt == BN) {
                [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
                    [[unroll]] for (uint e = 0u; e < 8u; ++e) {
                        mx = max(mx, s[qq][kk][e]);
                    }
                }
            } else {
                [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
                    [[unroll]] for (uint e = 0u; e < 8u; ++e) {
                        if (kk * TILE + 2u * e + half < cnt) {
                            mx = max(mx, s[qq][kk][e]);
                        }
                    }
                }
            }
            mx = max(mx, subgroupShuffleXor(mx, 16u));
            float mo = runMax[qq];
            float mn = max(mo, mx);
            runMax[qq] = mn;
            // exp2(-inf - m) is 0: the first block's correction, no special case.
            float corr = exp2(mo - mn);
            [[unroll]] for (uint j = 0u; j < HDT; ++j) {
                [[unroll]] for (uint e = 0u; e < 8u; ++e) {
                    o[qq][j][e] *= corr;
                }
            }
            float sum = 0.0;
            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
                // P^T narrowed to fp16, two keys a word: w[i] holds this
                // lane's keys 4i + half and 4i + 2 + half.
                uint w[4];
                [[unroll]] for (uint i = 0u; i < 4u; ++i) {
                    float p0 = exp2(s[qq][kk][2u * i] - mn);
                    float p1 = exp2(s[qq][kk][2u * i + 1u] - mn);
                    if (cnt < BN) {
                        uint k0 = kk * TILE + 4u * i + half;
                        p0 = k0 < cnt ? p0 : 0.0;
                        p1 = k0 + 2u < cnt ? p1 : 0.0;
                    }
                    f16vec2 h = f16vec2(p0, p1);
                    sum += float(h.x) + float(h.y);
                    w[i] = packFloat2x16(h);
                }
                // B wants keys 0..15 of this lane's query in order. The other
                // half-wave holds the other parity; swap and interleave.
                [[unroll]] for (uint i = 0u; i < 4u; ++i) {
                    f16vec2 mine = unpackFloat2x16(w[i]);
                    f16vec2 theirs = unpackFloat2x16(subgroupShuffleXor(w[i], 16u));
                    f16vec2 even = half == 0u ? mine : theirs;   // keys 4i, 4i+2
                    f16vec2 odd = half == 0u ? theirs : mine;    // keys 4i+1, 4i+3
                    fragP[qq][kk][4u * i] = even.x;
                    fragP[qq][kk][4u * i + 1u] = odd.x;
                    fragP[qq][kk][4u * i + 2u] = even.y;
                    fragP[qq][kk][4u * i + 3u] = odd.y;
                }
            }
            runSum[qq] = runSum[qq] * corr + sum;
        }

        // ---- O^T += V^T . P^T.
        [[unroll]] for (uint j = 0u; j < HDT; ++j) {
            FRAG_A fragV[KTIL];
            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
                coopMatLoad(fragV[kk], hact, vBase + ((base / TILE + kk) * HDT + j) * (TILE * TILE),
                    TILE, gl_CooperativeMatrixLayoutRowMajor);
            }
            [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
                [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
                    o[qq][j] = coopMatMulAdd(fragV[kk], fragP[qq][kk], o[qq][j]);
                }
            }
        }
    }

    // ---- Epilogue: the two halves' sums make the denominator; O^T goes out
    // column-major, which is O row-major at the output projection's stride.
    // The rows past the sequence are written too, as the plain build does:
    // they are the A operand's pad rows, which nothing reads.
    [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
        float inv = 1.0 / (runSum[qq] + subgroupShuffleXor(runSum[qq], 16u));
        [[unroll]] for (uint j = 0u; j < HDT; ++j) {
            ACC r = o[qq][j];
            [[unroll]] for (uint e = 0u; e < 8u; ++e) {
                r[e] *= inv;
            }
            coopMatStore(ACCH(r), hact,
                pc.outOff + (q0 + qq * TILE) * pc.lda + head * HEAD_DIM + j * TILE,
                pc.lda, gl_CooperativeMatrixLayoutColumnMajor);
        }
    }
}

